def order_cost(qty, unit_price, threshold, discount):
    """Стоимость заказа qty единиц в рублях, округлённая до копейки."""
    if isinstance(qty, bool) or not isinstance(qty, int):
        raise TypeError("qty must be an integer")
    if qty < 0:
        raise ValueError("qty must be non-negative")

    if isinstance(unit_price, float):
        price = Decimal(str(unit_price))
    elif isinstance(unit_price, bool):
        raise TypeError("unit_price must be a number or string")
    elif isinstance(unit_price, int):
        price = Decimal(unit_price)
    elif isinstance(unit_price, Decimal):
        price = unit_price
    elif isinstance(unit_price, str):
        price = Decimal(unit_price)
    else:
        raise TypeError("unit_price must be a number or string")
    if price < 0:
        raise ValueError("unit_price must be non-negative")

    if discount is None:
        discount = Decimal(0)
    elif isinstance(discount, float):
        discount = Decimal(str(discount))
    elif isinstance(discount, bool):
        raise TypeError("discount must be a number")
    elif isinstance(discount, int):
        discount = Decimal(discount)
    elif isinstance(discount, Decimal):
        pass
    elif isinstance(discount, str):
        discount = Decimal(discount)
    else:
        raise TypeError("discount must be a number")
    if discount < 0 or discount >= 1:
        raise ValueError("discount must be in [0, 1)")

